  ('pina', 20, 'PINA (PT. Pina Aplikasi Bersama)', array['android', 'iOS'], 'React Native', 3, array['React Native', 'Javascript', 'Redux', 'Firebase', 'OAuth', 'VSCode', 'Android Studio', 'Xcode', 'Figma'], 'pdfs/works-at-pina.pdf'),
  ('tataskola', 30, 'Tataskola (Subsidiary of Pintek)', array['android', 'iOS'], 'React Native', 1, array['React Native', 'Javascript', 'Redux', 'Figma'], 'pdfs/works-at-tataskola.pdf'),
