insert into public.experience_translations (experience_key, locale, period, title, location, description, bullets) values
  ('transnovasi', 'en', 'Nov 2023 — Present', 'Mobile Engineer', 'Jakarta', 'Sole Mobile Developer for two critical mobile apps for Korlantas Polri (Indonesian National Police Traffic Corps) within the K3I national project.', array['Improved the Operation Support App: real-time officer tracking, device monitoring, operational activity reporting for command center situational awareness', 'Integrated Livekit for real-time video call capabilities', 'Enhanced stability by refactoring legacy code, implementing robust error handling, restructuring codebases into scalable atomic components', 'Contributed to the Public App: citizen access to Korlantas services (licensing, traffic info, news)', 'Operated in a highly agile environment, collaborating with frontend web and backend teams', 'Implemented Sentry for crash reporting and performance monitoring']),
  ('transnovasi', 'id', 'Nov 2023 — Sekarang', 'Mobile Engineer', 'Jakarta', 'Satu-satunya Pengembang Mobile untuk dua aplikasi penting Korlantas Polri dalam proyek nasional K3I.', array['Memperbaiki Aplikasi Dukungan Operasi: pelacakan GPS petugas real-time, pemantauan perangkat, pelaporan aktivitas operasional untuk kesadaran situasional pusat komando', 'Mengintegrasikan Livekit untuk kemampuan video call real-time', 'Meningkatkan stabilitas dengan refactoring kode lama, menerapkan penanganan error yang kuat, merestrukturisasi codebase menjadi komponen atomik yang scalable', 'Berkontribusi pada Aplikasi Publik: akses masyarakat ke layanan Korlantas (SIM, info lalu lintas, berita)', 'Beroperasi dalam lingkungan agile, berkolaborasi dengan tim frontend web dan backend', 'Mengimplementasikan Sentry untuk pelaporan crash dan pemantauan kinerja']),
  ('transnovasi', 'ja', '2023年11月 — 現在', 'モバイルエンジニア', 'ジャカルタ', 'K3I国家プロジェクトにおけるインドネシア国家警察交通部隊（Korlantas Polri）の2つの重要なモバイルアプリの唯一のモバイル開発者。', array['作戦支援アプリの改善：現場担当者のリアルタイムGPS追跡、デバイス監視、指揮センターの状況認識のための活動報告', 'リアルタイムビデオ通話機能のためのLivekit統合', 'レガシーコードのリファクタリング、堅牢なエラーハンドリングの実装、スケーラブルなアトミックコンポーネントへのコードベース再構築による安定性向上', '公共アプリへの貢献：Korlantasサービスへの市民アクセス（免許、交通情報、ニュース）', 'フロントエンドWebおよびバックエンドチームと協力し、高度にアジャイルな環境で運用', 'クラッシュレポートとパフォーマンス監視のためのSentry実装']),
  ('pina', 'en', 'May 2022 — Nov 2023', 'Mobile Engineer', 'Jakarta', 'Comprehensive wealth management app offering personalized finance advisory, net worth tracking, financial goal management, and investment options.', array['Refurbished authentication: implemented OAuth for Google and Apple login', 'Redesigned Home screen, account registration, and churning survey', 'Applied atomic component design principles to restructure UI folder', 'Developed the Advice feature: financial planning tool for consulting certified financial planners', 'Collaborated on core features: Invest, NetWorth, Save', 'Integrated AppsFlyer for attribution tracking and marketing analytics']),
  ('pina', 'id', 'Mei 2022 — Nov 2023', 'Mobile Engineer', 'Jakarta', 'Aplikasi manajemen kekayaan komprehensif yang menawarkan penasihat keuangan personal, pelacakan kekayaan bersih, manajemen tujuan keuangan, dan opsi investasi.', array['Memperbarui autentikasi: mengimplementasikan OAuth untuk login Google dan Apple', 'Mendesain ulang layar Beranda, registrasi akun, dan survei churning', 'Menerapkan prinsip desain komponen atomik untuk merestrukturisasi folder UI', 'Mengembangkan fitur Advice: alat perencanaan keuangan untuk konsultasi dengan perencana keuangan bersertifikat', 'Berkolaborasi pada fitur inti: Invest, NetWorth, Save', 'Mengintegrasikan AppsFlyer untuk pelacakan atribusi dan analitik pemasaran']),
  ('pina', 'ja', '2022年5月 — 2023年11月', 'モバイルエンジニア', 'ジャカルタ', 'パーソナライズされた財務アドバイザリー、純資産追跡、財務目標管理、投資オプションを提供する包括的な資産管理アプリ。', array['認証の刷新：GoogleおよびAppleログインのOAuth実装', 'ホーム画面、アカウント登録、チャーニング調査の再設計', 'UIフォルダの再構築のためのアトミックコンポーネントデザイン原則の適用', 'Advice機能の開発：認定ファイナンシャルプランナーとの相談用財務計画ツール', 'コア機能での協力：Invest、NetWorth、Save', 'アトリビューション追跡とマーケティング分析のためのAppsFlyer統合']),
  ('tataskola', 'en', 'Nov 2021 — Apr 2022', 'Junior Mobile Developer', 'Jakarta', 'School administration platform for handling school-based payments via online transactions.', array['Built pixel-perfect UIs for 5 core screens using mock data: Authentication, Home, Student List, Transaction List, Account', 'Achieved 95%+ design match across breakpoints; reduced rework by 70% via reusable components', 'Established mock API/data layer and API contracts for future backend integration', 'Structured modular component architecture; standardized design tokens and styles']),
  ('tataskola', 'id', 'Nov 2021 — Apr 2022', 'Junior Mobile Developer', 'Jakarta', 'Platform administrasi sekolah untuk menangani pembayaran berbasis sekolah melalui transaksi online.', array['Membangun UI pixel-perfect untuk 5 layar utama menggunakan data mock: Autentikasi, Beranda, Daftar Siswa, Daftar Transaksi, Akun', 'Mencapai kesesuaian desain 95%+ di semua breakpoint; mengurangi pengerjaan ulang 70% melalui komponen reusable', 'Membuat layer mock API/data dan kontrak API untuk integrasi backend di masa depan', 'Menyusun arsitektur komponen modular; menstandarisasi design token dan style']),
  ('tataskola', 'ja', '2021年11月 — 2022年4月', 'ジュニアモバイル開発者', 'ジャカルタ', 'オンライン取引による学校ベースの支払いを処理するための学校管理プラットフォーム。', array['モックデータを使用した5つのコア画面のピクセルパーフェクトUI構築：認証、ホーム、生徒一覧、取引一覧、アカウント', '全ブレークポイントで95%以上のデザイン一致を達成；再利用可能なコンポーネントにより手戻りを70%削減', '将来のバックエンド統合のためのモックAPI/データレイヤーとAPIコントラクトの確立', 'モジュラーコンポーネントアーキテクチャの構築；デザイントークンとスタイルの標準化']),
  ('tkd', 'en', 'Oct 2020 — Oct 2021', 'Android Developer', 'Jakarta', 'Developed two apps: Kupon Makan (food coupon donation system) and Koop (digital savings and loan cooperative).', array['Kupon Makan: Redesigned UI with bottom navigation, coupon-style components, notification and donor statistics screens', 'Koop: Led full UI/UX refurbishment, executed framework migration from Android WebView to React Native', 'Integrated APIs and finalized screen builds; Koop moved to internal testing in ~2 months', 'Standardized front-end patterns for consistency and maintainability']),
  ('tkd', 'id', 'Okt 2020 — Okt 2021', 'Android Developer', 'Jakarta', 'Mengembangkan dua aplikasi: Kupon Makan (sistem donasi kupon makanan) dan Koop (koperasi simpan pinjam digital).', array['Kupon Makan: Mendesain ulang UI dengan bottom navigation, komponen gaya kupon, layar notifikasi dan statistik donatur', 'Koop: Memimpin pembaruan UI/UX secara menyeluruh, melakukan migrasi framework dari Android WebView ke React Native', 'Mengintegrasikan API dan menyelesaikan pembuatan layar; Koop masuk ke pengujian internal dalam ~2 bulan', 'Menstandarisasi pola front-end untuk konsistensi dan kemudahan pemeliharaan']),
  ('tkd', 'ja', '2020年10月 — 2021年10月', 'Android開発者', 'ジャカルタ', '2つのアプリを開発：Kupon Makan（フードクーポン寄付システム）とKoop（デジタル貯蓄貸付協同組合）。', array['Kupon Makan：ボトムナビゲーション、クーポンスタイルコンポーネント、通知および寄付者統計画面によるUI再設計', 'Koop：UI/UXの全面刷新をリード、Android WebViewからReact Nativeへのフレームワーク移行を実行', 'APIの統合と画面構築の完了；Koopは約2ヶ月で内部テストに移行', '一貫性と保守性のためのフロントエンドパターンの標準化'])
insert into public.projects (key, sort_order, title, short_title, company, short_company, tech_stack, short_stack, play_store_url, app_store_url, logo_path, logo_bg, logo_size) values
