  ('kuponMakan', 50, 'Kupon Makan', null, 'PT. Teknologi Kupon Digital', null, array['Java (Android)', 'PHP', 'Sentry', 'WebView'], array['Java (Android)', 'PHP'], null, null, 'app-logos/kupon_makan.png', '#ffffff', null),
