insert into public.project_translations (project_key, locale, description, details, platform) values
  ('operationSupport', 'en', 'A mission-critical mobile app built for Korlantas Polri command center — enabling real-time GPS tracking of field officers, device monitoring, operational activity reporting, and on-premise voice/video communication via LiveKit.', array['Migrated legacy JavaScript codebase to TypeScript (3 months)', 'Migrated to Turbo Monorepo architecture for code sharing and modularity', 'Implemented real-time GPS officer tracking and device monitoring', 'Integrated on-premise LiveKit for voice/video communication', 'Built Atomic Component architecture — custom components, no UI Kit'], 'Android (primary), iOS (testing)'),
  ('operationSupport', 'id', 'Aplikasi mobile mission-critical yang dibangun untuk pusat komando Korlantas Polri — memungkinkan pelacakan GPS real-time petugas lapangan, pemantauan perangkat, pelaporan aktivitas operasional, dan komunikasi suara/video on-premise melalui LiveKit.', array['Memigrasikan codebase JavaScript lama ke TypeScript (3 bulan)', 'Memigrasikan ke arsitektur Turbo Monorepo untuk berbagi kode dan modularitas', 'Mengimplementasikan pelacakan GPS petugas dan pemantauan perangkat real-time', 'Mengintegrasikan LiveKit on-premise untuk komunikasi suara/video', 'Membangun arsitektur Komponen Atomik — komponen kustom, tanpa UI Kit'], 'Android (utama), iOS (testing)'),
  ('operationSupport', 'ja', 'Korlantas Polri指揮センター向けに構築されたミッションクリティカルなモバイルアプリ — 現場担当者のリアルタイムGPS追跡、デバイス監視、活動報告、LiveKitによるオンプレミス音声/ビデオ通信を実現。', array['レガシーJavaScriptコードベースをTypeScriptに移行（3ヶ月）', 'コード共有とモジュール性のためのTurbo Monorepoアーキテクチャへの移行', 'リアルタイムGPS担当者追跡とデバイス監視の実装', '音声/ビデオ通信のためのオンプレミスLiveKit統合', 'アトミックコンポーネントアーキテクチャの構築 — カスタムコンポーネント、UIキット不使用'], 'Android（メイン）、iOS（テスト）'),
  ('publicApp', 'en', 'A citizen-facing mobile app providing access to Korlantas latest news and digital services — SINAR (driver''s license), SIGNAL (vehicle registration), IRSMS (accident reporting), ETLE (traffic enforcement), Balik Desa (homecoming navigation), and regional police office directories.', array['Integrated WebView for multiple Korlantas digital service platforms', 'Migrated repository into Turbo Monorepo structure', 'Implemented Atomic Component architecture consistent with Operation Support App'], 'Android & iOS'),
  ('publicApp', 'id', 'Aplikasi mobile untuk masyarakat yang menyediakan akses ke berita terbaru Korlantas dan layanan digital — SINAR (SIM), SIGNAL (registrasi kendaraan), IRSMS (pelaporan kecelakaan), ETLE (penegakan lalu lintas), Balik Desa (navigasi mudik), dan direktori kantor polisi daerah.', array['Mengintegrasikan WebView untuk berbagai platform layanan digital Korlantas', 'Memigrasikan repository ke dalam struktur Turbo Monorepo', 'Mengimplementasikan arsitektur Komponen Atomik yang konsisten dengan Aplikasi Dukungan Operasi'], 'Android & iOS'),
  ('publicApp', 'ja', 'Korlantasの最新ニュースとデジタルサービスへのアクセスを提供する市民向けモバイルアプリ — SINAR（運転免許）、SIGNAL（車両登録）、IRSMS（事故報告）、ETLE（交通取締）、Balik Desa（帰省ナビ）、地方警察署ディレクトリ。', array['複数のKorlantasデジタルサービスプラットフォームへのWebView統合', 'リポジトリのTurbo Monorepo構造への移行', '作戦支援アプリと一貫したアトミックコンポーネントアーキテクチャの実装'], 'Android & iOS'),
  ('pina', 'en', 'A comprehensive wealth management app offering personalized financial advisory, net worth tracking, financial goal management, and investment in stocks and mutual funds.', array['Implemented OAuth authentication (Google & Apple login)', 'Redesigned Home, registration, and churning survey screens', 'Built Advice feature for certified financial planner consultations', 'Integrated AppsFlyer for attribution tracking', 'Contributed to core Invest, NetWorth, and Save modules'], 'Android & iOS'),
  ('pina', 'id', 'Aplikasi manajemen kekayaan komprehensif yang menawarkan penasihat keuangan personal, pelacakan kekayaan bersih, manajemen tujuan keuangan, dan investasi saham serta reksa dana.', array['Mengimplementasikan autentikasi OAuth (login Google & Apple)', 'Mendesain ulang layar Beranda, registrasi, dan survei churning', 'Membangun fitur Advice untuk konsultasi perencana keuangan bersertifikat', 'Mengintegrasikan AppsFlyer untuk pelacakan atribusi', 'Berkontribusi pada modul inti Invest, NetWorth, dan Save'], 'Android & iOS'),
  ('pina', 'ja', 'パーソナライズされた財務アドバイザリー、純資産追跡、財務目標管理、株式および投資信託への投資を提供する包括的な資産管理アプリ。', array['OAuth認証の実装（Google & Appleログイン）', 'ホーム、登録、チャーニング調査画面の再設計', '認定ファイナンシャルプランナー相談用のAdvice機能構築', 'アトリビューション追跡のためのAppsFlyer統合', 'コアモジュールInvest、NetWorth、Saveへの貢献'], 'Android & iOS'),
  ('tataskola', 'en', 'A school administration mobile app enabling guardians to manage school-based payments through online transactions. Built from scratch based on Figma designs with a CI/CD pipeline for Google Play deployment.', array['Built 5 core screens from scratch: Auth, Home, Student List, Transaction List, Account', 'Achieved ≥95% design match across breakpoints (pixel-perfect UI)', 'Reduced rework by 70% through reusable components and design tokens', 'Defined API contracts and mock services for backend integration', 'Set up automated deployment pipeline to Google Play'], 'Android & iOS'),
  ('tataskola', 'id', 'Aplikasi mobile administrasi sekolah yang memungkinkan wali murid mengelola pembayaran berbasis sekolah melalui transaksi online. Dibangun dari nol berdasarkan desain Figma dengan pipeline CI/CD untuk deployment Google Play.', array['Membangun 5 layar utama dari nol: Auth, Beranda, Daftar Siswa, Daftar Transaksi, Akun', 'Mencapai kesesuaian desain ≥95% di semua breakpoint (pixel-perfect UI)', 'Mengurangi pengerjaan ulang 70% melalui komponen reusable dan design token', 'Mendefinisikan kontrak API dan layanan mock untuk integrasi backend', 'Menyiapkan pipeline deployment otomatis ke Google Play'], 'Android & iOS'),
  ('tataskola', 'ja', '保護者がオンライン取引で学校ベースの支払いを管理できる学校管理モバイルアプリ。Figmaデザインに基づいてゼロから構築し、Google Playデプロイメント用のCI/CDパイプラインを備える。', array['5つのコア画面をゼロから構築：Auth、ホーム、生徒一覧、取引一覧、アカウント', '全ブレークポイントで95%以上のデザイン一致を達成（ピクセルパーフェクトUI）', '再利用可能なコンポーネントとデザイントークンにより手戻りを70%削減', 'バックエンド統合のためのAPIコントラクトとモックサービスの定義', 'Google Playへの自動デプロイメントパイプラインの構築'], 'Android & iOS'),
  ('kuponMakan', 'en', 'A social impact Android app designed as a digital enabler during COVID-19. Simplifies a coupon-based donation system where donors contribute food coupons to beneficiaries, redeemable at registered vendors.', array['UI/UX redesign: introduced bottom navigation and coupon-style card components', 'Implemented donor-to-vendor messaging system APIs', 'Developed Notifications, Coupon Messages, Donor Testimonials & Statistics screens', 'Standardized front-end patterns for consistency and maintainability'], 'Android'),
  ('kuponMakan', 'id', 'Aplikasi Android berdampak sosial yang dirancang sebagai enabler digital selama COVID-19. Menyederhanakan sistem donasi berbasis kupon di mana donatur menyumbangkan kupon makanan kepada penerima manfaat, yang dapat ditukarkan di vendor terdaftar.', array['Redesain UI/UX: memperkenalkan bottom navigation dan komponen kartu bergaya kupon', 'Mengimplementasikan API sistem pesan donatur-ke-vendor', 'Mengembangkan layar Notifikasi, Pesan Kupon, Testimonial Donatur & Statistik', 'Menstandarisasi pola front-end untuk konsistensi dan kemudahan pemeliharaan'], 'Android'),
  ('kuponMakan', 'ja', 'COVID-19期間中のデジタルイネーブラーとして設計された社会貢献型Androidアプリ。寄付者が受益者にフードクーポンを寄付し、登録店舗で引き換えられるクーポンベースの寄付システムを簡素化。', array['UI/UX再設計：ボトムナビゲーションとクーポンスタイルカードコンポーネントの導入', '寄付者から店舗へのメッセージングシステムAPIの実装', '通知、クーポンメッセージ、寄付者の声＆統計画面の開発', '一貫性と保守性のためのフロントエンドパターンの標準化'], 'Android'),
  ('koop', 'en', 'A digital financial services app modernizing savings and loan cooperative (koperasi) activities. Enables members to manage savings, apply for loans, and transfer money between members and external bank accounts.', array['Led full UI/UX redesign to modernize the application', 'Executed complete framework migration from Java WebView to React Native', 'Integrated required APIs and finalized screen builds', 'Delivered test-ready build within approximately 2 months'], 'Android'),
  ('koop', 'id', 'Aplikasi layanan keuangan digital yang memodernisasi aktivitas koperasi simpan pinjam. Memungkinkan anggota mengelola tabungan, mengajukan pinjaman, dan mentransfer uang antar anggota dan rekening bank eksternal.', array['Memimpin redesain UI/UX secara menyeluruh untuk memodernisasi aplikasi', 'Melakukan migrasi framework lengkap dari Java WebView ke React Native', 'Mengintegrasikan API yang diperlukan dan menyelesaikan pembuatan layar', 'Menyelesaikan build siap uji dalam waktu sekitar 2 bulan'], 'Android'),
  ('koop', 'ja', '貯蓄貸付協同組合（コペラシ）の活動を近代化するデジタル金融サービスアプリ。会員が貯蓄管理、ローン申請、会員間および外部銀行口座への送金を行えるようにする。', array['アプリケーションの近代化のための全面的なUI/UX再設計をリード', 'Java WebViewからReact Nativeへの完全なフレームワーク移行を実行', '必要なAPIの統合と画面構築の完了', '約2ヶ月でテスト対応ビルドを完成'], 'Android')
