-- One-time import of the content that used to live in src/data/*.ts and messages/*.json.
-- Safe to re-run: existing rows are overwritten by key.

begin;

on conflict (key) do update set sort_order = excluded.sort_order, company = excluded.company, platforms = excluded.platforms,
  framework = excluded.framework, team_size = excluded.team_size, tech_stack = excluded.tech_stack, pdf_path = excluded.pdf_path;

on conflict (experience_key, locale) do update set period = excluded.period, title = excluded.title, location = excluded.location,
  description = excluded.description, bullets = excluded.bullets;

on conflict (key) do update set sort_order = excluded.sort_order, title = excluded.title, short_title = excluded.short_title,
  company = excluded.company, short_company = excluded.short_company, tech_stack = excluded.tech_stack, short_stack = excluded.short_stack,
  play_store_url = excluded.play_store_url, app_store_url = excluded.app_store_url, logo_path = excluded.logo_path,
  logo_bg = excluded.logo_bg, logo_size = excluded.logo_size;

on conflict (project_key, locale) do update set description = excluded.description, details = excluded.details,
  platform = excluded.platform;

commit;
